#!/usr/bin/env python3
"""Install E24 corrected M-family replay-router into the Kaggle repository."""

from __future__ import annotations
from datetime import datetime
from pathlib import Path
import base64, hashlib, textwrap, zlib

ROOT = Path(__file__).resolve().parent
BUNDLE = ROOT / "artifacts" / "bundles" / "current"
TARGET = BUNDLE / "agent_e24_m_family_corrected.py"
EXP_DIR = ROOT / "experiments" / "e024_m_family_corrected"
README = EXP_DIR / "README.md"
INDEX = ROOT / "docs" / "experiment_index.md"
HISTORY = ROOT / "EXPERIMENT_RUN_HISTORY.md"

AGENT_B64 = """"""
EXPECTED_SHA = "d99d0af14b5eea553aedf20d6c2f6b7f96670131406a2a4dd2c92ee64390ee98"

def main():
    print("=== Install E24: corrected M-family replay-router ===")
    print("Repository root:", ROOT)
    if not BUNDLE.exists():
        raise SystemExit("Run this from the Kaggle repository root.")

    agent_text = zlib.decompress(base64.b64decode(AGENT_B64)).decode("utf-8")
    compile(agent_text, str(TARGET), "exec")
    actual = hashlib.sha256(agent_text.encode("utf-8")).hexdigest()
    if actual != EXPECTED_SHA:
        raise SystemExit(f"Embedded hash mismatch: {actual} != {EXPECTED_SHA}")

    TARGET.write_text(agent_text, encoding="utf-8")

    EXP_DIR.mkdir(parents=True, exist_ok=True)
    README.write_text(textwrap.dedent(f"""\
    # E24 — Corrected M-family replay-router

    E23 failed because replay actions were aligned to the wrong state index and
    donor cash-flow timing was overwritten.

    E24 fixes the mechanism rather than patching outcomes:

    - live step `t` uses replay action `t+1`;
    - replay positions at `t` remain the start-state positions for remapping;
    - donor HIRE / BUY_LAND timing is preserved;
    - donor purchase ordering is preserved;
    - shop-prefix route switching remains;
    - invalid unit actions and impossible SELL quantities are still repaired.

    This is still a complete M-family candidate, separate from E21/E22.

    SHA256: `{actual}`
    """), encoding="utf-8")

    if INDEX.exists():
        txt = INDEX.read_text(encoding="utf-8")
        if "| E24 |" not in txt:
            row = (
                "| E24 | Corrected M-family replay-router (replay t+1 alignment; donor cash-flow preserved) | "
                "`artifacts/bundles/current/agent_e24_m_family_corrected.py` | "
                "smoke pending | independent M-family candidate | "
                "fixes E23 implementation failure; E23 remains immutable |\n"
            )
            marker = "\n## Legacy non-E series"
            if marker in txt:
                txt = txt.replace(marker, "\n" + row + marker)
            else:
                txt = txt.rstrip() + "\n" + row
            INDEX.write_text(txt, encoding="utf-8")

    now = datetime.now().astimezone().isoformat(timespec="seconds")
    if not HISTORY.exists():
        HISTORY.write_text("# Experiment Run History\n\n", encoding="utf-8")
    with HISTORY.open("a", encoding="utf-8") as f:
        f.write(
            f"## {now} — Install E24 corrected M-family replay-router\n\n"
            f"- Agent: `{TARGET.relative_to(ROOT)}`\n"
            f"- SHA256: `{actual}`\n"
            "- Fixes E23 replay action/state off-by-one.\n"
            "- Preserves donor HIRE/BUY_LAND/purchase ordering.\n"
            "- E23 is not overwritten.\n"
            "- No Kaggle submission performed.\n\n"
        )

    print("Wrote:", TARGET.relative_to(ROOT))
    print("SHA256:", actual)
    print("Wrote:", README.relative_to(ROOT))
    print("=== E24 install complete ===")

if __name__ == "__main__":
    main()
